{"implementation": "def solve(case):
    payload = case['payload']
    nodes = payload['nodes']
    required_symbols = set(payload['required_symbols'])
    node_map = {n['id']: n for n in nodes}
    children = {n['id']: [] for n in nodes}
    for n in nodes:
        p = n.get('parent')
        if p is not None:
            children[p].append(n['id'])
    retained = set(n['id'] for n in nodes)
    # sort nodes by depth descending, then id ascending
    sorted_nodes = sorted(nodes, key=lambda n: (-n['depth'], n['id']))
    removal_order = []
    for n in sorted_nodes:
        nid = n['id']
        if nid not in retained:
            continue
        if not n['removable']:
            continue
        if nid == 'root':
            continue
        if n['symbol'] in required_symbols:
            continue
        # check that node has no retained children
        has_retained_child = any(child in retained for child in children[nid])
        if has_retained_child:
            continue
        # tentative removal: all required symbols still represented?
        # Since we already skip required symbols, removal cannot eliminate a required symbol.
        # But we still check to be safe.
        symbol_counts = {}
        for rnid in retained:
            sym = node_map[rnid]['symbol']
            symbol_counts[sym] = symbol_counts.get(sym, 0) + 1
        # remove this node's contribution temporarily
        symbol_counts[n['symbol']] -= 1
        if any(symbol_counts.get(s, 0) <= 0 for s in required_symbols):
            continue
        # perform removal
        retained.remove(nid)
        removal_order.append(nid)
    return {
        'retained': sorted(retained),
        'removal_order': removal_order
    }"}
